"""Small visual dashboard for the first TraceTrust vertical slice."""

from fastapi.responses import HTMLResponse


def dashboard() -> HTMLResponse:
    return HTMLResponse("""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>TraceTrust</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#f4f7fb}body{margin:0}header{background:#12213a;color:#fff;padding:28px 7vw}main{max-width:1180px;margin:28px auto;padding:0 24px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#fff;border:1px solid #e0e6ef;border-radius:14px;padding:18px;box-shadow:0 4px 14px #13233a0d}.metric{font-size:32px;font-weight:700}.muted{color:#667085;font-size:13px}.controls{display:flex;gap:10px;margin:22px 0}input,button{padding:11px;border:1px solid #cbd5e1;border-radius:8px;font:inherit}button{background:#2e6bff;color:#fff;border:0;cursor:pointer}.panel{margin-top:18px}.row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eef2f6}.severity-high,.severity-critical{color:#c2410c;font-weight:700}.score{color:#18794e;font-weight:700}@media(max-width:750px){.grid{grid-template-columns:1fr}}
</style></head><body><header><strong>TraceTrust</strong><div class="muted" style="color:#c7d2fe">Auditable traceability analytics</div></header>
<main><div class="controls"><label>Snapshot <select id="snapshot" onchange="loadSnapshot()"></select></label><label>Lote <select id="lot" onchange="loadLot()"></select></label></div><div class="grid" id="metrics"></div><div class="grid"><section class="card panel"><h2>Trust Score</h2><div id="trust">Selecciona un lote.</div></section><section class="card panel"><h2>Findings</h2><div id="findings">Cargando...</div></section><section class="card panel"><h2>Genealogía</h2><div id="lineage">Selecciona un lote.</div></section></div></main>
<script>
let snapshot='';
async function get(path){const r=await fetch(path);if(!r.ok)throw new Error(await r.text());return r.json()}
async function loadSnapshot(){snapshot=document.getElementById('snapshot').value;const s=await get('/snapshots/'+snapshot),lots=await get('/lots/'+snapshot);document.getElementById('metrics').innerHTML=`<div class="card"><div class="muted">Eventos</div><div class="metric">${s.event_count}</div></div><div class="card"><div class="muted">Lotes</div><div class="metric">${s.lot_count}</div></div><div class="card"><div class="muted">Trust promedio</div><div class="metric score">${s.average_trust_score??'—'}</div></div>`;document.getElementById('lot').innerHTML=lots.items.map(x=>`<option value="${x.lot_id}">${x.lot_id} · ${x.trust_score??'—'}</option>`).join('');loadLot()}
async function loadLot(){const lot=document.getElementById('lot').value;if(!lot)return;try{const [t,l,f]=await Promise.all([get(`/trust/${snapshot}/${lot}`),get(`/lots/${snapshot}/${lot}/lineage?direction=both&depth=4`),get(`/findings/${snapshot}`)]);document.getElementById('trust').innerHTML=`<div class="metric score">${t.score.toFixed(2)}/100</div><div class="muted">${t.explanation}</div>`;const nodes=[...(l.ancestors?.nodes||[]),...(l.descendants?.nodes||[])];document.getElementById('lineage').innerHTML=nodes.filter(n=>n.node_type==='event').map(n=>`<div class="row"><span>${n.label}</span><span class="muted">${n.properties.event_type}</span></div>`).join('')||'Sin eventos';document.getElementById('findings').innerHTML=f.items.filter(x=>x.entity_ids.includes(lot)).map(x=>`<div class="row"><span>${x.rule_id}</span><span class="severity-${x.severity}">${x.severity}</span></div>`).join('')||'Sin findings'}catch(e){document.getElementById('trust').textContent='No se pudo cargar el lote'}}
async function boot(){const snapshots=await get('/snapshots');document.getElementById('snapshot').innerHTML=snapshots.items.map(x=>`<option value="${x.snapshot_id}">${x.snapshot_id}</option>`).join('');loadSnapshot()}boot();
</script></body></html>""")
